import fs from 'node:fs';import v8 from 'node:v8';import path from 'node:path';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';
const root=process.cwd(),p='plans/260925-documentation-authority-unification/',r=p+'reports/phase-06/',s='/tmp/fgos-work/resume-truth/',read=f=>JSON.parse(fs.readFileSync(f)),write=(f,x)=>fs.writeFileSync(f,JSON.stringify(x,null,2)+'\n'),pin=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),label=process.argv[2]||'truth';
const gen=await import(path.join(root,'scripts/generate-doc-inventory.mjs')),g=await import(path.join(root,'scripts/check-doc-inventory-gates.mjs'));
const old=read(r+'working-identity-registry.json');fs.copyFileSync(s+'identity-registry-sync.json',s+'identity-registry.json');
let registry=read(s+'identity-registry.json');if(!gen.registryBindsToCommit(registry.commit,pin,root)){console.log('Carry start',new Date().toISOString());registry=gen.carryForwardIdentityRegistryRepoWide(root,{commit:pin,identityRegistryPath:s+'identity-registry.json'});fs.writeFileSync(s+'identity-registry.json',JSON.stringify(registry)+'\n');console.log('Carried',JSON.stringify(registry.carryForward));}
console.log('Generate start',new Date().toISOString());const inv=gen.generateInventory(root,{commit:pin,identityRegistryPath:s+'identity-registry.json'});console.log('Generated',inv.items.length,inv.claimLedger.length,new Date().toISOString());try{const cache=v8.serialize(inv);fs.writeFileSync(s+'native-sync-cache.bin',cache);console.log('Complete enumerable native-output cache saved',cache.length);}catch(error){console.log('Optional cache unavailable',error.message);}
const bytes=fs.readFileSync(s+'identity-registry.json'),known=j=>['units','retiredUnits','identityGaps'].flatMap(k=>j[k]),ids=new Set(known(registry).map(u=>u.claimId));assert(known(old).every(u=>ids.has(u.claimId)));assert(bytes.length<90000000);const tuple=u=>JSON.stringify([u.claimId,u.sourcePath,u.sourceAnchor,u.sourceUnitDigest]);assert.deepEqual(inv.claimLedger.map(tuple).sort(),registry.units.map(tuple).sort());
const beforeIDs=new Set(known(old).map(u=>u.claimId)),oldLive=new Set(old.units.map(u=>u.claimId)),oldById=new Map(old.units.map(u=>[u.claimId,u]));write(s+label+'-native-accounting.json',{pin,carryForward:registry.carryForward,newUnits:registry.units.filter(u=>!beforeIDs.has(u.claimId)),changedUnits:registry.units.filter(u=>{const b=oldById.get(u.claimId);return b&&tuple(b)!==tuple(u)}),newGaps:registry.identityGaps.filter(u=>oldLive.has(u.claimId)),newRetired:registry.retiredUnits.filter(u=>oldLive.has(u.claimId)),ledger:inv.claimLedger.filter(u=>u.sourcePath.startsWith('docs/')),registryBytes:bytes.length});
const vocabulary=read(p+'claim-and-disposition-vocabulary.json'),droppedClaimsRegister=read(p+'dropped-claims-register.json'),decisions=[...g.loadDecisionShards(p+'pilot/decisions'),...g.loadDecisionShards(p+'ledger/decisions')],scope=read(r+'candidate-unverified-root-authorities.json').scope,ratchetResult=g.loadRatchetResult(root),runs=[];
const priors=[p+'reports/identity-registry.json',p+'reports/phase-02-identity-registry.json'],scopes={root:scope,agent:['docs/architect/agent-coordination'],packaging:['docs/architect/packaging-distribution','docs/specs/distribution.md']},union=[...new Set(Object.values(scopes).flat())];
for(const strict of [false,true]){console.log('Check',strict?'E union':'D','both priors',new Date().toISOString());const result=g.checkInventory({repoRoot:root,inventory:inv,vocabulary,identityRegistry:registry,droppedClaimsRegister,previousRegistries:priors.map(read),ratchetResult,strict,headCommit:pin,registryBytes:bytes,missingInputs:[],decisions,scope:strict?union:null});write(s+label+'-'+(strict?'E':'D')+'.json',result);runs.push({check:strict?'E':'D',priors,scope:strict?union:null,result});console.log('Result',result.fatalFindings.length,JSON.stringify(result.conservationOpen.map(x=>[x.type,x.count])));}
const applied=g.applyDecisions(inv,decisions,{vocabulary,targetAnchorsOf:g.buildTargetAnchorLookup(root,pin),targetUnitDigestOf:g.buildTargetUnitDigestLookup(root,pin),unitsOf:g.buildConservationUnitLookup(root,pin),registry,repoRoot:root}),batchConservation={};for(const [batch,scope0] of Object.entries(scopes)){console.log('Native batch conservation',batch);batchConservation[batch]=g.checkConservation({inventory:applied.inventory,registry:applied.registry,previousRegistries:priors.map(read),vocabulary,droppedClaimsRegister,ratchetResult,scope:scope0,decisions,repoRoot:root});}
write(s+label+'-proof.json',{pin,commands:['native generateInventory (all fields)','native checkInventory D and union-scoped E with both previousRegistries in each invocation','native applyDecisions + checkConservation for individual batch list equality'],native:{items:inv.items.length,claims:inv.claimLedger.length,knownBefore:known(old).length,knownAfter:known(registry).length,zeroKnownIDLoss:true,activeTupleEquality:true,compactOneLine:true,bytes:bytes.length,SHA256:crypto.createHash('sha256').update(bytes).digest('hex')},bothPriorsCheckedTogether:true,runs,batchConservation,helperSource:fs.readFileSync(import.meta.filename,'utf8')});
console.log('Done',new Date().toISOString());
